cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#include <cfloat>
#include <cstdint>
template <typename T>
__global__ void max_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    long outer_size, long reduce_size, long inner_size)
{
    // Coalesced reduction kernel: threadIdx.x indexes CONTIGUOUS inner
    // elements, so every warp's 32 lanes read 32 consecutive floats from
    // global memory (fully coalesced 128B transactions) instead of the
    // widely-strided per-lane accesses of a warp-shuffle-over-reduction
    // scheme. threadIdx.y splits the (large-stride) reduction dimension
    // across warps; each thread first reduces its own strided slice of
    // the reduction dimension locally (also using __ldg), and a small
    // shared-memory tree reduction then combines the per-warp partial
    // maxima into the final result for each inner column. A grid-stride
    // loop over inner-dimension tiles (blockIdx.x) and the outer
    // dimension (blockIdx.y) covers arbitrarily large tensors.
    extern __shared__ unsigned char smem_raw[];
    T* __restrict__ sdata = reinterpret_cast<T*>(smem_raw); // [blockDim.y][blockDim.x]
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int bdx = blockDim.x;
    const int bdy = blockDim.y;
    const long inner_stride = (long)bdx * (long)gridDim.x;
    for (long inner_idx = (long)blockIdx.x * bdx + tx; inner_idx < inner_size; inner_idx += inner_stride) {
        for (long outer_idx = blockIdx.y; outer_idx < outer_size; outer_idx += (long)gridDim.y) {
            const T* __restrict__ col_base = X + outer_idx * reduce_size * inner_size + inner_idx;
            T local_max = (T)(-FLT_MAX);
            for (long r = ty; r < reduce_size; r += bdy) {
                T v = __ldg(col_base + r * inner_size);
                local_max = v > local_max ? v : local_max;
            }
            sdata[ty * bdx + tx] = local_max;
            __syncthreads();
            #pragma unroll
            for (int stride = 16; stride > 0; stride >>= 1) {
                if (bdy > stride && ty < stride) {
                    T other = sdata[(ty + stride) * bdx + tx];
                    T cur = sdata[ty * bdx + tx];
                    sdata[ty * bdx + tx] = other > cur ? other : cur;
                }
                __syncthreads();
            }
            if (ty == 0) {
                Y[outer_idx * inner_size + inner_idx] = sdata[tx];
            }
            __syncthreads(); // safe reuse of shared memory for next outer_idx iteration
        }
    }
}
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    int64_t ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = x_c.sizes();
    long outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= sizes[i];
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];
    std::vector<int64_t> out_sizes;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }
    auto y = torch::empty(out_sizes, x_c.options());
    const int threads_x = 32;  // one warp width -> coalesced reads along inner dim
    const int threads_y = 8;   // splits the reduction dimension across warps
    dim3 block(threads_x, threads_y);
    long grid_x = (inner_size + (long)threads_x - 1) / (long)threads_x;
    if (grid_x < 1) grid_x = 1;
    if (grid_x > 1024) grid_x = 1024;
    long grid_y = outer_size < 65535 ? outer_size : 65535;
    if (grid_y < 1) grid_y = 1;
    dim3 grid((unsigned int)grid_x, (unsigned int)grid_y);
    size_t smem_bytes = (size_t)threads_x * (size_t)threads_y * sizeof(float);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    max_reduce_kernel<float><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        y.data_ptr<float>(),
        outer_size, reduce_size, inner_size
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "max_reduce_kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["max_reduce_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
